CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, email_verified_at TEXT, password TEXT NOT NULL, remember_token TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, contact_name TEXT, email TEXT, phone TEXT, postcode TEXT, notes TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE jobs (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL, status TEXT NOT NULL, current_working_revision_id INTEGER, issued_revision_id INTEGER, accepted_revision_id INTEGER, issued_at TEXT, booked_at TEXT, completed_at TEXT, lost_at TEXT, internal_notes TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE weekly_fuel_prices (id INTEGER PRIMARY KEY, week_commencing TEXT NOT NULL, source TEXT NOT NULL, price_per_litre_inc_vat NUMERIC NOT NULL, is_active INTEGER NOT NULL, activated_at TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE rate_settings (id INTEGER PRIMARY KEY, name TEXT NOT NULL, depot_postcode TEXT NOT NULL, miles_per_gallon NUMERIC NOT NULL, litres_per_gallon NUMERIC NOT NULL, maintenance_per_mile NUMERIC NOT NULL, unloaded_add_on_per_mile NUMERIC NOT NULL, loaded_add_on_per_mile NUMERIC NOT NULL, two_horse_multiplier NUMERIC, is_active INTEGER NOT NULL, effective_from TEXT, effective_until TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE job_revisions (id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL, weekly_fuel_price_id INTEGER, rate_setting_id INTEGER, revision_number INTEGER NOT NULL, horse_count INTEGER NOT NULL, depot_postcode_override TEXT, pickup_postcode TEXT, dropoff_postcode TEXT, notes TEXT, engine_total NUMERIC NOT NULL, final_total NUMERIC, manual_final_total_reason TEXT, calculation_explanation TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE route_legs (id INTEGER PRIMARY KEY, job_revision_id INTEGER NOT NULL, sequence INTEGER NOT NULL, label TEXT NOT NULL, start_postcode TEXT, end_postcode TEXT, miles INTEGER NOT NULL, manual_miles INTEGER, rate_type TEXT NOT NULL, rate_per_mile NUMERIC, amount NUMERIC, created_at TEXT, updated_at TEXT);
